  t.ok(IB.HERO_RING.glow < IB.HERO_RING.rim, 'and the disc is quieter than its edge');
  t.ok(IB.HERO_RING.rx > IB.HERO_RING.ry, 'the disc lies flat on the deck, like every other ground shape');

